// Hanyang University Seoul campus package. Data is generated by scripts/campuses/hanyang/build-package.mjs from the pilot
// (pilot/hanyang-seoul round 6, whole campus): 58 destructible models, 6 protected hospital models (한양대병원, shield), and a
// baked ground (terrain surfaces, forecourt / amphitheatre bowl / stadium site layer, context backdrop, planting) that the engine
// reads instead of building its own (pkg.ground.baked, pkg.terrain.heightGrids).
import { WORLD_UNITS_PER_METER, GEO_ORIGIN, HANYANG_PLACEMENTS, HANYANG_PROTECTED, HANYANG_BUILDING_BASE, HANYANG_HEIGHT_GRIDS, HANYANG_HEIGHT_RANGE_M, HANYANG_ENV_IDS, HANYANG_GROUND_LOOK, HANYANG_PROVENANCE } from './data.js?v=hy64';
import { HANYANG_FOOTPRINTS } from './footprints.js?v=hy64';

const MODEL_IDS = Object.freeze(HANYANG_PLACEMENTS.map(p => p.id));
const asset = file => new URL(`../../../assets/campuses/hanyang/${file}`, import.meta.url).href;

export const HANYANG = Object.freeze({
  id: 'hanyang',
  meta: Object.freeze({ school: '한양대학교', campus: '서울캠퍼스', short: '한양대 서울', modelNoun: '한양대' }),
  geo: Object.freeze({ origin: GEO_ORIGIN, worldUnitsPerMeter: WORLD_UNITS_PER_METER }),
  placements: HANYANG_PLACEMENTS,
  approvedCount: HANYANG_PLACEMENTS.length,
  additionalCount: 0,
  coreIds: Object.freeze(['main', 'history', 'amphitheater', 'paiknamLibrary', 'studentWelfare', 'chungMongKoo']),
  startBuildingId: 'main',
  models: Object.freeze({
    manifests: Object.freeze([
      Object.freeze({ url: asset('manifest.json'), expectedIds: MODEL_IDS }),
      Object.freeze({ url: asset('environment.json'), expectedIds: HANYANG_ENV_IDS }),
    ]),
    proceduralIds: Object.freeze([]),
    createProceduralSource: () => { throw new Error('No procedural buildings in this campus'); },
    enhanceFacade: () => ({ stats: {}, dispose() {} }),
  }),
  // Finished display ground of the pilot (pads on the real outlines, forecourt and bowl levels already in it).
  terrain: Object.freeze({ heightGrids: HANYANG_HEIGHT_GRIDS, buildingBase: HANYANG_BUILDING_BASE,
    source: 'Relative terrain estimate (SRTM via Mapzen/Terrain Tiles + photo/plan constraints, pilot/hanyang-seoul); not a survey' }),
  environment: Object.freeze({ provenance: HANYANG_PROVENANCE, sourceNote: 'OSM ground surfaces (© OpenStreetMap contributors, ODbL); site layer, planting and heights estimated' }),
  ground: Object.freeze({
    baked: Object.freeze({ envIds: HANYANG_ENV_IDS, castShadow: Object.freeze(['site-amphitheater-bowl', 'site-forecourt']), look: HANYANG_GROUND_LOOK, playMargin_m: 30, source: 'pilot/hanyang-seoul preview ground, baked' }),
  }),
  // Protected hospitals (src/protected-buildings.js): six 한양대병원 models, never destructible, shield reaction; loaded from their
  // own manifest so the destructible list and its progress are unchanged. Floors at the pilot base (baseY), not sampled.
  protected: Object.freeze({
    manifestURL: asset('protected.json'),
    models: HANYANG_PROTECTED,
  }),
  // Hazard tape around every destructible building (src/engine/hazard-tape.js, user decision 2026-10-18).
  hazardTape: Object.freeze({ footprints: HANYANG_FOOTPRINTS }),
  scene: Object.freeze({
    background: '#c9d6dc', fog: Object.freeze({ color: '#c9d6dc', near: 700, far: 2200 }),
    hemisphere: Object.freeze({ sky: '#eef2f4', ground: '#7d8576', intensity: 1.2 }),
    sun: Object.freeze({ color: '#fff4e2', intensity: 2.6, position: Object.freeze([-100, 220, 120]), shadowSpan: 185 }),
    floor: Object.freeze({ color: '#7f8669', hidden: true, y: HANYANG_HEIGHT_RANGE_M[0] * WORLD_UNITS_PER_METER - .3 }),
  }),
});
export default HANYANG;
